package pose
import("testing";"os";"path/filepath";"strings")
func TestB38R6CompatibilityCategory(t *testing.T){
 r:=newReleaseRepo(t,"v1.0.0")
 cp:=ChangelogPolicy{SchemaVersion:1,Categories:[]string{"compatibility"}}
 r.body="---\nspec: alpha\ncategory: compatibility\nbreaking: false\n---\n\nRequired release content.\n"
 fs:=[]ReleaseFragment{{Spec:"alpha",Category:"compatibility",Path:"alpha.md",Body:"Required release content.",Digest:ReleaseDigest(r.body)}}
 r.manifest=NewReleaseManifest(r.version,"","2026-10-02T00:00:00Z",fs,fixtureReleasePolicy(),cp,r.manifest.VersionEvidence)
 r.notes=RenderReleaseNotes(r.version,fs,cp)
 r.notes=strings.Replace(r.notes,"Required release content.","False replacement.",1)
 r.manifest.NotesDigest=ReleaseDigest(r.notes);r.writeAll(t)
 relWrite(t,r.root,".pose/policy/changelog.json",string(CanonicalJSON(cp)))
 gaps,limits:=ReleaseCandidateGaps(r.root,r.version,&r.manifest)
 t.Logf("candidate gaps=%v limits=%v",gaps,limits)
 snap:=snapshotOf(t,tagged(t,r));t.Logf("snapshot intact=%v gaps=%v limits=%v",snap.Intact(),snap.Gaps,snap.Limits)
 if len(gaps)==0||snap.Intact(){t.Error("materially false notes accepted as compatibility-only difference")}
}
func TestB38R6GitPolicyAncestor(t *testing.T){
 r:=newReleaseRepo(t,"v1.0.0")
 raw,err:=os.ReadFile(filepath.Join(r.root,".pose/policy/release.json"));if err!=nil{t.Fatal(err)}
 relWrite(t,r.root,".pose/release-policy.json",string(raw))
 os.RemoveAll(filepath.Join(r.root,".pose/policy"));if err:=os.Symlink("lost-policy",filepath.Join(r.root,".pose/policy"));err!=nil{t.Fatal(err)}
 snap:=snapshotOf(t,tagged(t,r));t.Logf("snapshot intact=%v gaps=%v issues=%v",snap.Intact(),snap.Gaps,snap.Issues)
 if snap.Intact(){t.Error("policy ancestor is a link, not absence; accepted legacy fallback and default changelog")}
}
func TestB38R6RelativeAbsence(t *testing.T){
 root:=t.TempDir();t.Chdir(root)
 if err:=os.Symlink("lost", ".pose");err!=nil{t.Fatal(err)}
 absent,err:=ProvenAbsent(".pose/releases");t.Logf("absent=%v err=%v",absent,err)
 status,serr:=(Store{Root:"."}).GetReleaseStatus("");t.Logf("status=%+v err=%v",status,serr)
 if absent&&err==nil||serr==nil{t.Error("relative root masks lost ancestor as absence")}
}
func TestB38R6LowVariants(t *testing.T){
 t.Run("null kind",func(t *testing.T){r:=newReleaseRepo(t,"v1.0.0");policy:=ReleasePolicy{SchemaVersion:1};r.manifest=NewReleaseManifest(r.version,"","2026-10-02T00:00:00Z",r.manifest.Fragments,policy,ChangelogPolicy{},map[string]string{"source":EngineVersionFile,"kind":"","value":r.version});raw:=strings.Replace(string(CanonicalJSON(r.manifest)),`"kind": ""`,`"kind": null`,1);_,issues:=ValidateReleaseManifestBytes([]byte(raw),r.version);t.Logf("null kind issues=%v",issues)})
 t.Run("README archive",func(t *testing.T){r:=newReleaseRepo(t,"v1.0.0");relWrite(t,r.root,".pose/changelogs/v1.0.0/README.md","Auxiliary text\n");g,l:=ReleaseCandidateGaps(r.root,r.version,&r.manifest);s:=snapshotOf(t,tagged(t,r));t.Logf("candidate gaps=%v limits=%v snapshot gaps=%v",g,l,s.Gaps)})
}
func TestB38R6PolicyFileAncestor(t *testing.T){
 r:=newReleaseRepo(t,"v1.0.0");raw,_:=os.ReadFile(filepath.Join(r.root,".pose/policy/release.json"));relWrite(t,r.root,".pose/release-policy.json",string(raw));os.RemoveAll(filepath.Join(r.root,".pose/policy"));relWrite(t,r.root,".pose/policy","not a directory");s:=snapshotOf(t,tagged(t,r));t.Logf("file ancestor intact=%v gaps=%v",s.Intact(),s.Gaps);if s.Intact(){t.Error("policy ancestor blob is not absence")}
}
func TestB38R6LowByteIdenticalLinks(t *testing.T){
 r:=tagged(t,newReleaseRepo(t,"v1.0.0"));relWrite(t,r.root,"original-fragment.md",r.body);p:=filepath.Join(r.root,".pose/changelogs/v1.0.0/alpha.md");os.Remove(p);if err:=os.Symlink(filepath.Join(r.root,"original-fragment.md"),p);err!=nil{t.Fatal(err)}
 s,err:=(Store{Root:r.root}).GetReleaseStatus(r.version);_,loaderr:=LoadReleaseFragments(filepath.Dir(p),ChangelogPolicy{});t.Logf("tagged sound=%v err=%v archive loader=%v",s.Releases[0].Sound(),err,loaderr)
}
func TestB38R6HistoryInventory(t *testing.T){
 root:=os.Getenv("B38_REVIEW_ROOT");if root==""{t.Skip("explicit source repository not selected")};raw,err:=gitOutput(root,"tag","--list","v*");if err!=nil{t.Fatal(err)}
 total,intact,missing,other:=0,0,0,0
 for _,tag:=range strings.Fields(raw){if ValidateReleaseVersion(tag)!=nil{continue};total++;s,e:=ReadReleaseSnapshot(root,tag);if e!=nil{if strings.Contains(e.Error(),ErrReleaseSnapshotMissing.Error()){missing++}else{other++;t.Errorf("%s: %v",tag,e)};continue};if !s.Intact(){t.Errorf("%s: issues=%v gaps=%v",tag,s.Issues,s.Gaps)}else{intact++}}
 t.Logf("tags=%d intact=%d missing_snapshot=%d other_errors=%d",total,intact,missing,other)
}

