package cli
import("testing";"os";"path/filepath";"bytes";"strings";posemodel "github.com/harne8/pose-mcp/internal/pose")
func TestB38R6CheckerLostReleases(t *testing.T){
 for _,variant:=range []string{"dangling","file"}{t.Run(variant,func(t *testing.T){
 root:=cliReleaseRepo(t)
 m,err:=posemodel.LoadReleaseManifest(root,"v1.0.0");if err!=nil{t.Fatal(err)}
 p:=cliFixturePolicy("text");p.AdoptedAt="2026-10-01";p.Provider="github";p.Repository="o/r"
 m.PolicyDigest=posemodel.ReleaseDigest(p)
 // checker needs adopted policy; the release inventory itself is what is lost.
 writeCloseoutCLIFile(t,root,".pose/policy/release.json",string(posemodel.CanonicalJSON(p)))
 os.RemoveAll(filepath.Join(root,".pose/releases"))
 if variant=="dangling"{if err:=os.Symlink("lost-releases",filepath.Join(root,".pose/releases"));err!=nil{t.Fatal(err)}}else{writeCloseoutCLIFile(t,root,".pose/releases","not a directory")}
 var out bytes.Buffer
 c:=&nativeChecker{root:root,mode:"strict",stdout:&out}
 appendReleasePolicyChecks(c);t.Logf("checker errors=%d output=%s",c.errors,out.String())
 _,serr:=(posemodel.Store{Root:root}).GetReleaseStatus("");t.Logf("status error=%v",serr)
 if c.errors==0{t.Error("release checker accepted a lost release inventory")}
 })}
}
func TestB38R6PrepareChangelogPolicy(t *testing.T){
 for _,raw:=range []string{`{"schema_version":999}`,`{broken`}{t.Run(raw,func(t *testing.T){
 root,target:=preparedEngineReleaseWith(t,true)
 os.RemoveAll(filepath.Join(root,".pose/releases",target));os.RemoveAll(filepath.Join(root,".pose/changelogs",target));os.Remove(filepath.Join(root,".pose/changelogs",target+".md"))
 writeCloseoutCLIFile(t,root,".pose/policy/changelog.json",raw)
 var out,errs bytes.Buffer
 code:=cmdReleasePrepare(root,[]string{"--version",target,"--apply"},&out,&errs)
 gaps,_:=checkRelease(root,target)
 t.Logf("prepare code=%d out=%s err=%s check gaps=%v",code,out.String(),errs.String(),gaps)
 if code==0&&!strings.Contains(errs.String(),"policy"){t.Error("prepare writes a cut that its own checker rejects for policy")}
 })}
}
func TestB38R6PlanLostInventory(t *testing.T){
 root,target:=preparedEngineReleaseWith(t,true)
 os.RemoveAll(filepath.Join(root,".pose/releases"));if err:=os.Symlink("lost-inventory",filepath.Join(root,".pose/releases"));err!=nil{t.Fatal(err)}
 _,_,previous,_,err:=releaseInputs(root,target);t.Logf("previous=%q err=%v",previous,err)
 if err==nil{t.Error("release plan interprets lost release inventory as no previous releases")}
}
func TestB38R6CompatibilityConsumerParity(t *testing.T){
 root:=cliReleaseRepo(t)
 policy:=cliFixturePolicy("text"); cp:=posemodel.ChangelogPolicy{SchemaVersion:1,Categories:[]string{"compatibility"}}
 body:="---\nspec: alpha\ncategory: compatibility\nbreaking: false\n---\n\nRequired content.\n"
 fs:=[]posemodel.ReleaseFragment{{Spec:"alpha",Category:"compatibility",Body:"Required content.",Path:"alpha.md",Digest:posemodel.ReleaseDigest(body)}}
 m:=posemodel.NewReleaseManifest("v1.0.0","","2026-10-02T00:00:00Z",fs,policy,cp,evidenceFor("text"))
 notes:=strings.Replace(posemodel.RenderReleaseNotes("v1.0.0",fs,cp),"Required content.","False content.",1);m.NotesDigest=posemodel.ReleaseDigest(notes)
 writeCloseoutCLIFile(t,root,".pose/policy/changelog.json",string(posemodel.CanonicalJSON(cp)))
 writeCloseoutCLIFile(t,root,".pose/changelogs/v1.0.0/alpha.md",body)
 writeCloseoutCLIFile(t,root,".pose/changelogs/v1.0.0.md",notes)
 writeCloseoutCLIFile(t,root,".pose/releases/v1.0.0/manifest.json",string(posemodel.CanonicalJSON(m)))
 relGitCLI(t,root,"add","-A");relGitCLI(t,root,"commit","-qm","custom category cut");relGitCLI(t,root,"tag","v1.0.0")
 gaps,_:=checkRelease(root,"v1.0.0");s,err:=(posemodel.Store{Root:root}).GetReleaseStatus("v1.0.0")
 t.Logf("check gaps=%v status sound=%v err=%v",gaps,s.Releases[0].Sound(),err)
 var out,errs bytes.Buffer
 code:=cmdReleaseNotesSnapshot(root,[]string{"--version","v1.0.0"},&out,&errs);t.Logf("notes code=%d text=%s",code,out.String())
 if len(gaps)==0||s.Releases[0].Sound()||code==0{t.Error("consumers accepted materially altered notes")}
}
func TestB38R6HistoricalCategoryPolicy(t *testing.T){
 root:=cliReleaseRepo(t)
 p:=cliFixturePolicy("text");p.AdoptedAt="2026-10-01";p.Provider="github";p.Repository="o/r"
 m,_:=posemodel.LoadReleaseManifest(root,"v1.0.0")
 m2:=posemodel.NewReleaseManifest(m.Version,m.PreviousVersion,m.PreparedAt,m.Fragments,p,posemodel.ChangelogPolicy{},m.VersionEvidence)
 writeCloseoutCLIFile(t,root,".pose/policy/release.json",string(posemodel.CanonicalJSON(p)))
 writeCloseoutCLIFile(t,root,".pose/releases/v1.0.0/manifest.json",string(posemodel.CanonicalJSON(m2)))
 relGitCLI(t,root,"add","-A");relGitCLI(t,root,"commit","-qm","adopted cut");relGitCLI(t,root,"tag","v1.0.0")
 writeCloseoutCLIFile(t,root,".pose/policy/changelog.json",`{"schema_version":1,"categories":["added"]}`)
 var out bytes.Buffer;c:=&nativeChecker{root:root,mode:"strict",stdout:&out};appendReleasePolicyChecks(c)
 gaps,_:=checkRelease(root,"v1.0.0");s,err:=(posemodel.Store{Root:root}).GetReleaseStatus("v1.0.0")
 t.Logf("checker errors=%d out=%s check gaps=%v sound=%v err=%v",c.errors,out.String(),gaps,s.Releases[0].Sound(),err)
 if c.errors!=0{t.Error("a later valid changelog policy invalidates a legitimate historical cut in the checker")}
}
func TestB38R6LowHumanLimits(t *testing.T){
 root:=cliReleaseRepoKind(t,"engine");relGitCLI(t,root,"tag","v1.0.0")
 var out,errs bytes.Buffer;code:=cmdReleaseStatus(root,nil,&out,&errs)
 t.Logf("status code=%d text=%s",code,out.String())
 s,err:=(posemodel.Store{Root:root}).GetReleaseStatus("v1.0.0");t.Logf("JSON snapshot limits=%v err=%v",s.Releases[0].Snapshot.Limits,err)
}
